      con.setBalancesC(String.valueOf(ContractSMC.parseDouble(con.getBalancesC(), ChaincodeConstants.balance) + (ContractSMC.parseDouble(djt.get(ts.toString()), ChaincodeConstants.Djt)) * pmax - ContractSMC.parseDouble(con.getDmj(), ChaincodeConstants.Dmj) * pN));
      balances.set(ContractSMC.parseInteger(con.getIc(), ChaincodeConstants.asset_index), 0.0);
      request = stub.invokeChaincodeWithStringArgs(ChaincodeConstants.consumerContract, ChaincodeConstants.transfer, con.getIc(), String.valueOf(ContractSMC.parseDouble(con.getBalancesC(), ChaincodeConstants.balance) + (ContractSMC.parseDouble(djt.get(ts.toString()), ChaincodeConstants.Djt)) * pmax - ContractSMC.parseDouble(con.getDmj(), ChaincodeConstants.Dmj) * pN), smcString, channelName);
      if (request.getStatusCode() != ChaincodeConstants.SUCCESS_STATUS) {
        ContractSMC.handleError("Error invoking consumer transfer " + request.getMessage());
      }
      smcString = request.getStringPayload();
      if (smcString == null || smcString.isEmpty()) {
        ContractSMC.handleError("No smc from invoked consumer transfer");
      }
      smc = ContractSMC.genson.deserialize(smcString, new GenericType<SmartContractData>() {});
