  /**
   *  register - Registers the prosumer/consumer from i
   *  Registers a prosumer or consumer into the SmartContractData structure at index `i`. 
   *  - For a prosumer: Adds their asset to the list of registered prosumers if not already present.
   *  - For a consumer: Adds their asset to the list of registered consumers if not already present.
   *  - In both cases, it also removes the registered asset from the list of "init" (unregistered) entries. 
   *  @param ctx           The Fabric transaction context.
   *  @param arg     List of arguments (e.g. nameN, ijN, assetN).
   *  @param channelName   The channel name (not used in the method logic).
   *  @return              String "done" if registration is successful.
   */
  @Transaction(intent = Transaction.TYPE.SUBMIT)
  public String register(Context ctx, final String name, final String ij, final String channelName) {
    // Get Fabric stub
    ChaincodeStub stub = ctx.getStub();
    Chaincode.Response request = null;
    // Input variables
    Integer ijN = 0;
    String nameN = "";
    String assetN = ChaincodeConstants.empty_json_string;
    nameN = String.valueOf(name);
    ijN = Integer.valueOf(ij);
    // Get the current SMC from the ledger
    String smcString = stub.getStringState(ChaincodeConstants.SMC);
    SmartContractData smc = ContractSMC.genson.deserialize(smcString, new GenericType<SmartContractData>() {});
    // === Prosumer Registration ===
    if (nameN.equalsIgnoreCase(ChaincodeConstants.PROSUMER)) {
      String prosString = smc.getRegisteredProsumers();
      List<String> regs = ContractSMC.genson.deserialize(prosString, new GenericType<List<String>>() {});
      String prosVString = smc.getInitPros();
      List<String> regsInit = ContractSMC.genson.deserialize(prosVString, new GenericType<List<String>>() {});
      // If index i is valid (not already registered)
      if (regs.size() <= ijN) {
        regs.add(assetN);
        regsInit.remove(assetN);
      } else {
        ContractSMC.handleError("Error registering prosumer. It is already in the list. ");
      }
      // Serialize updated lists and save to SMC
      String assetSerialized = ContractSMC.genson.serialize(regs);
      smc.setRegisteredProsumers(assetSerialized);
      assetSerialized = ContractSMC.genson.serialize(smc);
      stub.putStringState(ChaincodeConstants.SMC, assetSerialized);
      // === Consumer Registration ===
    } else if (nameN.equalsIgnoreCase(ChaincodeConstants.CONSUMER)) {
      String consString = smc.getInitCons();
      List<String> consInit = ContractSMC.genson.deserialize(consString, new GenericType<List<String>>() {});
      String regsString = (request != null ? request.getStringPayload() : null);
      List<String> regs = ContractSMC.genson.deserialize(regsString, new GenericType<List<String>>() {});
      // If index i is valid (not already registered)
      if (regs.size() <= ijN) {
        regs.add(assetN);
        consInit.remove(assetN);
      } else {
        ContractSMC.handleError("Error registering consumer. It is already in the list. ");
      }
      // Serialize updated lists and save to SMC
      String assetSerialized = ContractSMC.genson.serialize(regs);
      smc.setRegisteredConsumers(assetSerialized);
      assetSerialized = ContractSMC.genson.serialize(smc);
      stub.putStringState(ChaincodeConstants.SMC, assetSerialized);
    }
    return "done";
  }
  /**
   *  proInit - Add the prosumer to the list of registered prosumers, if it is not already in the list
   *  proInit - Adds a prosumer to the list of registered prosumers if it is not already registered.
   *  The prosumer is taken from the "initPros" list inside SmartContractData at the index specified by `assetI`.
   *  If the prosumer is already registered (based on the index), an error is thrown.
   *  Otherwise, the prosumer is added to the registered prosumers list and the updated data is saved to the ledger.
   *  @param ctx           The transaction context provided by Fabric.
   *  @param arg     List of arguments including:
   *                       - assetI: The index of the prosumer in the initPros list to register.
   *                       - smcStringN: The current serialized SmartContractData JSON string.
   *  @param channelName   The channel name (not used inside this function).
   *  @return              The updated serialized SmartContractData JSON string after registration.
   */
  @Transaction(intent = Transaction.TYPE.SUBMIT)
  public String proInit(Context ctx, final String timestampP, final String ip, final String smcstring, final String channelName) {
    // Obtain Fabric chaincode stub
    ChaincodeStub stub = ctx.getStub();
    // Variables for inputs
    String assetI = ChaincodeConstants.ZERO_INT;
    String smcStringN = "";
    SmartContractData smc = null;
    assetI = ip;
    smcStringN = smcstring;
    // Deserialize SmartContractData from provided JSON string
    smc = ContractSMC.genson.deserialize(smcStringN, SmartContractData.class);
    // Deserialize the initial (unregistered) prosumers list
    String initProsString = smc.getInitPros();
    ArrayList<ProsumerData> initPros = ContractSMC.genson.deserialize(initProsString, new GenericType<ArrayList<ProsumerData>>() {});
    // Deserialize the currently registered prosumers list
    String regProsString = smc.getRegisteredProsumers();
    // Handle case where registered prosumers list might be null or empty
    if (regProsString == null || regProsString.isEmpty()) {
      ContractSMC.logger.error("No reg pros in pro init");
      regProsString = ChaincodeConstants.empty_array_string;
    }
    ArrayList<ProsumerData> regPros = ContractSMC.genson.deserialize(regProsString, new GenericType<ArrayList<ProsumerData>>() {});
    ContractSMC.logger.info("==========2======");
    ContractSMC.logger.info(assetI);
    ContractSMC.logger.info(String.valueOf(initPros));
    // Check if prosumer at assetI index is already registered
    if (regPros.size() > ContractSMC.parseInteger(assetI, ChaincodeConstants.asset_index)) {
      ContractSMC.handleError("Prosumer with the given id already exists.");
    } else {
      regPros.add(initPros.get(ContractSMC.parseInteger(assetI, ChaincodeConstants.asset_index)));
    }
    // Serialize updated registered prosumers list back to JSON string
    regProsString = ContractSMC.genson.serialize(regPros);
    smc.setRegisteredProsumers(regProsString);
    // Serialize updated SmartContractData and save it back to ledger state
    smcStringN = ContractSMC.genson.serialize(smc);
    stub.putStringState(ChaincodeConstants.SMC, smcStringN);
    // Return updated SmartContractData JSON string
    return smcStringN;
  }
  /**
   *  conInit - Add the consumer to the list of registered consumers, if it is not already in the list
   *  conInit - Adds a consumer to the list of registered consumers if not already registered.
   *  The consumer is taken from the "initCons" list inside SmartContractData at the index specified by `assetI`. 
   *  If the consumer is already registered (based on the index), an error is thrown. 
   *  Otherwise, the consumer is added to the registered consumers list and the updated SmartContractData 
   *  is saved back to the ledger. 
   *  @param ctx           The transaction context provided by Fabric. 
   *  @param arg           List of arguments including: 
   *                       - assetI: The index of the consumer in the initCons list to register. 
   *                       - smcStringN: The current serialized SmartContractData JSON string. 
   *  @param channelName   The channel name (not used in this method). 
   *  @return              The updated serialized SmartContractData JSON string after registration.
   */
  @Transaction(intent = Transaction.TYPE.SUBMIT)
  public String conInit(Context ctx, final String timestampC, final String ic, final String smcstring, final String channelName) {
    // Variables to hold inputs
    String assetI = "";
    SmartContractData smc = null;
    String smcStringN = null;
    assetI = ic;
    smcStringN = smcstring;
    // Deserialize SmartContractData from JSON string
    smc = ContractSMC.genson.deserialize(smcStringN, SmartContractData.class);
    // Handle missing SmartContractData
    if (smc == null) {
      ContractSMC.handleError("No smc in conInit");
    }
    // Deserialize initial (unregistered) consumers list
    String initConsString = smc.getInitCons();
    if (initConsString == null || initConsString.isEmpty()) {
      initConsString = ChaincodeConstants.empty_array_string;
    }
    ArrayList<ConsumerData> initCons = ContractSMC.genson.deserialize(initConsString, new GenericType<ArrayList<ConsumerData>>() {});
    // Deserialize registered consumers list
    String regConsString = smc.getRegisteredConsumers();
    if (regConsString == null || regConsString.isEmpty()) {
      regConsString = ChaincodeConstants.empty_array_string;
    }
    ArrayList<ConsumerData> regCons = ContractSMC.genson.deserialize(regConsString, new GenericType<ArrayList<ConsumerData>>() {});
    // Check if consumer at index assetI already registered
    if (regCons.size() > ContractSMC.parseInteger(assetI, ChaincodeConstants.asset_index)) {
      ContractSMC.handleError("Consumer with the given id already exists.");

    } else {
      regCons.add(initCons.get(ContractSMC.parseInteger(assetI, ChaincodeConstants.asset_index)));
    }
    // Serialize updated registered consumers list and set in SmartContractData
    regConsString = ContractSMC.genson.serialize(regCons);
    smc.setRegisteredConsumers(regConsString);
    // Serialize updated SmartContractData and log info
    smcStringN = ContractSMC.genson.serialize(smc);
    ContractSMC.logger.info(smcStringN);
    ContractSMC.logger.info("-----------------------In cons init-----------------------");
    // Save updated SmartContractData back to ledger
    return smcStringN;
  }
  /**
   *  validateProsumer - Validates that Energy amount injected by prosumer i is greater than 
   *  Amount of intent to sell
   *  Validates whether the specified prosumer has injected enough energy 
   *  to support their intent to sell. 
   *  This evaluation transaction ensures that the injected energy (`Ei`) from a prosumer 
   *  at a given index is greater than or equal to the declared selling intent. 
   *  @param ctx          The transaction context provided by the Fabric runtime 
   *  @param $arg         A looped sequence of arguments  
   *  @param channelName  The name of the Fabric channel (not used directly in logic) 
   *  @return             "true" if injected energy ≥ selling intent, "false" otherwise
   */
  @Transaction(intent = Transaction.TYPE.EVALUATE)
  public String validateProsumer(Context ctx, final String timestamp, final String startDate, final String endDate, final String sit, final String ij, final String channelName) {
    // Get the stub for accessing ledger state
    ChaincodeStub stub = ctx.getStub();
    // Initialize input values
    Integer ijN = 0;
    String SiTN = ChaincodeConstants.ZERO_DOUBLE;
    SmartContractData smcc = null;
    SiTN = sit;
    ijN = Integer.valueOf(ij);
    // Default return value
    String flag = ChaincodeConstants.FALSE_STRING;
    // Fetch the smart contract data from the ledger
    String smcString = stub.getStringState(ChaincodeConstants.SMC);
    if (smcString == null || smcString.isEmpty()) {
      ContractSMC.handleError("No smc in validate");
    }
    // Deserialize the smart contract data
    smcc = ContractSMC.genson.deserialize(smcString, SmartContractData.class);
    // Get the registered prosumer list from the smart contract state
    String regsString = smcc.getRegisteredProsumers();
    if (regsString == null || regsString.isEmpty()) {
      ContractSMC.handleError("No reg pros in validate");
    }
    // Deserialize the list of registered prosumers
    GenericType<ArrayList<ProsumerData>> mapType = new GenericType<ArrayList<ProsumerData>>() {};
    ArrayList<ProsumerData> regs = ContractSMC.genson.deserialize(regsString, mapType);
    // Compare injected energy with selling intent
    if (ContractSMC.parseDouble(regs.get(ijN).getEi(), ChaincodeConstants.Ei) >= ContractSMC.parseDouble(SiTN, ChaincodeConstants.num)) {
      flag = ChaincodeConstants.TRUE_STRING;
    }
    // Log the result
    ContractSMC.logger.info("-----------validateProsumer---------");
    ContractSMC.logger.info(flag);
    // Return the evaluation result
    return flag;
  }
  /**
   *  validateConsumer - checks if consumer has enough balance
   *  Validates whether the specified consumer has enough balance to perform a transaction. 
   *  This evaluation transaction checks if the consumer at the given index has sufficient  
   *  monetary balance to support the required energy transaction  
   *  @param ctx          The transaction context from Hyperledger Fabric 
   *  @param $arg         A looped sequence of arguments 
   *  @param channelName  The channel where the transaction is evaluated (not used in logic) 
   *  @return             "true" if the consumer has enough balance, "false" otherwise
   */
  @Transaction(intent = Transaction.TYPE.EVALUATE)
  public String validateConsumer(Context ctx, final String timestamp, final String startDate, final String endDate, final String djt, final String pmax, final String ij, final String channelName) {
    // Access the Fabric stub for querying state
    ChaincodeStub stub = ctx.getStub();
    // Initialize variables
    Integer ijN = 0;
    String DjtN = ChaincodeConstants.ZERO_DOUBLE;
    Double pmaxN = 1.0;
    SmartContractData smcc = null;
    DjtN = djt;
    pmaxN = Double.valueOf(pmax);
    ijN = Integer.valueOf(ij);
    // Default result flag
    String flag = ChaincodeConstants.FALSE_STRING;
    // Retrieve current SmartContractData state
    String smcString = stub.getStringState(ChaincodeConstants.SMC);
    if (smcString == null || smcString.isEmpty()) {
      ContractSMC.handleError("No smc in validateConsumer");
    }
    // Deserialize SMC string into object
    smcc = ContractSMC.genson.deserialize(smcString, SmartContractData.class);
    // Get all registered consumers from SMC
    String regsString = smcc.getRegisteredConsumers();
    if (regsString == null || regsString.isEmpty()) {
      ContractSMC.handleError("No reg cons in in validateConsumer");
    }
    // Deserialize consumer list
    GenericType<ArrayList<ConsumerData>> mapType = new GenericType<ArrayList<ConsumerData>>() {};
    ArrayList<ConsumerData> regs = ContractSMC.genson.deserialize(regsString, mapType);
    // Check if consumer has enough balance
    if (ContractSMC.parseDouble(regs.get(ijN).getBalancesC(), ChaincodeConstants.balance) >= ContractSMC.parseDouble(DjtN, ChaincodeConstants.num) * pmaxN) {
      flag = ChaincodeConstants.TRUE_STRING;
    }
    // Log the validation result
    ContractSMC.logger.info("-----------validateConsumer---------");
    ContractSMC.logger.info(flag);
    // Return validation result
    return flag;
  }
