  /**
   *  registeredConsumerSet - Depending if the consumer exists in the list of registered consumers, it replaces
   *  the existing consumers or adds consumer to the list of registered consumers
   *  Registers or updates a consumer in the list of registered consumers in the SmartContractData (SMC). 
   *  If the consumer with the given identifier (index `ic`) already exists in the list, 
   *  their data is updated (replaced). Otherwise, the new consumer is added to the list. 
   *  @param ctx           The Fabric transaction context 
   *  @param arg           Parameters passed as serialized strings 
   *  @param channelName   The channel name (not directly used in the logic) 
   *  @return              Updated SMC object as a JSON string
   */
  @Transaction(intent = Transaction.TYPE.SUBMIT)
  public String registeredConsumerSet(Context ctx, final String asset, final String channelName) {
    // Get the chaincode stub
    ChaincodeStub stub = ctx.getStub();
    // Variable to hold the incoming serialized consumer data
    String conn = "";
    conn = asset;
    // Fetch the current SmartContractData from ledger
    String smcString = stub.getStringState(ChaincodeConstants.SMC);
    ContractSMC.logger.info(smcString);
    // Handle missing SMC data
    if (smcString == null || smcString.isEmpty()) {
      ContractSMC.handleError("No smc in RegisteredConsumerSet");
    }
    // Deserialize SMC data
    SmartContractData smc = ContractSMC.genson.deserialize(smcString, SmartContractData.class);
    String conString = conn;
    // Deserialize incoming consumer
    ConsumerData con = ContractSMC.genson.deserialize(conString, ConsumerData.class);
    // Get existing registered consumers from SMC
    String cons = smc.getRegisteredConsumers();
    ArrayList<ConsumerData> regcons = ContractSMC.genson.deserialize(cons, new GenericType<ArrayList<ConsumerData>>() {});
    // Extract identifier (ic) of the new consumer
    String ij = con.getIc();
    Boolean flag = false;
    // Check if consumer already exists in list
    for (ConsumerData cd : regcons) {
      if (ij.equals(cd.getIc())) {
        flag = true;
        break;
      }
    }
    // Replace or add consumer
    if (flag) {
      regcons.set(ContractSMC.parseInteger(ij, ChaincodeConstants.asset_index), con);
    } else {
      regcons.add(con);
    }
    // Update consumer list in SMC
    conString = ContractSMC.genson.serialize(regcons);
    smc.setRegisteredConsumers(conString);
    // Serialize and store updated SMC
    smcString = ContractSMC.genson.serialize(smc);
    stub.putStringState(ChaincodeConstants.SMC, smcString);
    // Return updated SMC JSON string
    return smcString;
  }
  /**
   *  registeredProsumerSet - Depending if the prosumer exists in the list of registsered prosumers,
   *  it replaces the existing prosumers or adds consumer to the list of registered prosumers 
   *  Registers or updates a prosumer in the list of registered prosumers in the SmartContractData (SMC). 
   *  If a prosumer with the same identifier (`ip`) already exists, their data is updated. 
   *  Otherwise, the new prosumer is added to the list. 
   *  @param ctx           The Fabric transaction context. 
   *  @param arg           Parameters passed (e.g. JSON serialized ProsumerData). 
   *  @param channelName   The name of the Fabric channel (not used in logic). 
   *  @return              Updated SMC object as a JSON string.
   */
  @Transaction(intent = Transaction.TYPE.SUBMIT)
  public String registeredProsumerSet(Context ctx, final String asset, final String channelName) {
    // Get the stub for chaincode operations
    ChaincodeStub stub = ctx.getStub();
    // Variable to hold serialized prosumer JSON string
    String pross = "";
    pross = asset;
    // Get current SmartContractData state from ledger
    String smcString = stub.getStringState(ChaincodeConstants.SMC);
    ContractSMC.logger.info(smcString);
    // Handle missing SmartContractData
    if (smcString == null || smcString.isEmpty()) {
      ContractSMC.handleError("No smc in setRegisteredProsumer");
    }
    // Deserialize the SMC JSON into an object
    SmartContractData smc = ContractSMC.genson.deserialize(smcString, SmartContractData.class);
    // Deserialize the incoming prosumer string into an objec
    String prostring = pross;
    ProsumerData pro = ContractSMC.genson.deserialize(prostring, ProsumerData.class);
    // Deserialize the existing list of registered prosumers
    ArrayList<ProsumerData> regpros = ContractSMC.genson.deserialize(smc.getRegisteredProsumers(), new GenericType<ArrayList<ProsumerData>>() {});
    // Check if prosumer with same index (ip) exists
    String ij = pro.getIp();
    Boolean flag = false;
    for (ProsumerData pd : regpros) {
      if (ij.equals(pd.getIp())) {
        flag = true;
        break;
      }
    }
    // Replace or add prosumer
    if (flag) {
      regpros.set(ContractSMC.parseInteger(ij, ChaincodeConstants.asset_index), pro);
    } else {
      regpros.add(pro);
    }
    // Serialize updated list and update and save SMC
    prostring = ContractSMC.genson.serialize(regpros);
    smc.setRegisteredProsumers(prostring);
    smcString = ContractSMC.genson.serialize(smc);
    stub.putStringState(ChaincodeConstants.SMC, smcString);
    // Return updated SMC as JSON string
    return smcString;
  }
